const crypto = require('crypto');
const event = $json.body ?? $json;
const timestamp = String($json.headers?.['x-lendloop-timestamp'] ?? '');
const signature = String($json.headers?.['x-lendloop-signature'] ?? '');
const now = Math.floor(Date.now() / 1000);
if (!/^\d{10}$/.test(timestamp) || Math.abs(now - Number(timestamp)) > 300) throw new Error('Rejected stale or invalid LendLoop timestamp');
const body = JSON.stringify(event);
const expected = crypto.createHmac('sha256', $env.LENDLOOP_N8N_SECRET).update(`${timestamp}.${body}`).digest('hex');
const suppliedBuffer = Buffer.from(signature, 'hex');
const expectedBuffer = Buffer.from(expected, 'hex');
if (suppliedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(suppliedBuffer, expectedBuffer)) throw new Error('Invalid LendLoop HMAC signature');
if (!event.loanId || !event.event || !event.toolName) throw new Error('Missing minimal request event fields');
return { json: { event: event.event, loanId: event.loanId, toolName: event.toolName, category: event.category, borrowerName: event.borrowerName, borrowerId: event.borrowerId, lenderId: event.lenderId, startDate: event.startDate, endDate: event.endDate, status: event.status, receivedAt: new Date().toISOString() } };

const { event, toolName, borrowerName, startDate, endDate, status, loanId } = $json;
const message = `LendLoop ${event}: ${toolName} (${startDate} to ${endDate}), status ${status}. Request ${loanId}.`;
console.log(JSON.stringify({ notification: message, recipientRole: event === 'requested' ? 'lender' : 'request participants' }));
return { json: { notification: message, loanId, event, status, loggedAt: new Date().toISOString() } };
